#!/usr/bin/env python3
"""Exercise navigation by name with the built binary, real shells, and pseudo-terminals.

Uses only Python's standard library and the Terminal helper from smoke.py. All
catalogs, settings, temporary files, and projects live in a temporary directory.
"""

import argparse
import json
import os
from pathlib import Path
import shlex
import shutil
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True  # Importing the shared helper leaves no cache in scripts/.
from smoke import Terminal  # noqa: E402

# The function generated by Projectory 1.0.0. People who update the binary keep
# it loaded until they run init again, so the new binary must keep serving it.
LEGACY_FUNCTION = r'''pt() {
  local _pt_file _pt_id _pt_path _pt_db _pt_status _pt_parse
  if [ "$#" -eq 1 ] && { [ "$1" = '~' ] || [ "$1" = "${HOME:-}" ]; }; then
    builtin cd
    return
  fi
  case "${1:-list}" in
    list|dash|go|-*)
      _pt_file="$(command mktemp "${TMPDIR:-/tmp}/projectory.XXXXXXXX")" || return
      BINARY "$@" --selection-file "$_pt_file"
      _pt_status=$?
      if [ "$_pt_status" -eq 0 ] && [ -s "$_pt_file" ]; then
        {
          IFS= read -r -d '' _pt_id && IFS= read -r -d '' _pt_path && IFS= read -r -d '' _pt_db
        } < "$_pt_file"
        _pt_parse=$?
        if [ "$_pt_parse" -eq 0 ] && [ -n "$_pt_id" ] && [ -n "$_pt_path" ] && [ -n "$_pt_db" ]; then
          if builtin cd -- "$_pt_path"; then
            BINARY _visit "$_pt_id" --path "$PWD" --db "$_pt_db" || command printf 'Projectory: no se pudo registrar la visita.\n' >&2
          else
            _pt_status=1
          fi
        else
          command printf 'Projectory: selección inválida.\n' >&2
          _pt_status=1
        fi
      fi
      command rm -f -- "$_pt_file"
      return "$_pt_status"
      ;;
    *) BINARY "$@" ;;
  esac
}
'''

ALTERNATE_SCREEN = b"\x1b[?1049h"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--binary", type=Path, default=Path(__file__).resolve().parents[1] / "bin/projectory")
    args = parser.parse_args()
    binary = args.binary.resolve()
    assert binary.is_file(), f"Build first: go build -o {binary} ./cmd/projectory"

    with tempfile.TemporaryDirectory(prefix="projectory-navigation-") as directory:
        root = Path(directory).resolve()
        database = root / "catalog.db"
        temporary = root / "tmp"
        temporary.mkdir()
        env = {**os.environ, "PROJECTORY_DATA_DIR": str(root / "unused-default"), "PROJECTORY_CONFIG_DIR": str(root / "config"), "PROJECTORY_BIN": str(binary), "DB": str(database), "ROOT": str(root), "TMPDIR": str(temporary)}

        def cli(*argv):
            result = subprocess.run([str(binary), *argv, "--db", str(database)], cwd=root, env=env, capture_output=True, text=True, timeout=30)
            assert result.returncode == 0, f"{argv}: {result.stderr}"
            return result

        def visits():
            return {record["path"]: record["visits"] for record in json.loads(cli("list", "--json").stdout)}

        def no_leftovers():
            assert not list(temporary.iterdir()), f"selection files left behind: {list(temporary.iterdir())}"
            assert not (root / "PWNED").exists() and not (root / "PWNED2").exists(), "a path was executed as code"

        shop = root / "mi tienda"
        old = root / "vieja $(touch PWNED) `touch PWNED2`; [x]"
        reserved = root / "reserved"
        blog = root / "blog"
        worktree = root / "external" / "blog-vista"
        for folder in (shop, old, reserved):
            folder.mkdir()
        cli("add", str(shop), "--name", "Mi Tienda")
        cli("add", str(old), "--name", "Tienda Vieja")
        cli("add", str(reserved), "--name", "add")
        subprocess.run(["git", "init", "-b", "main", str(blog)], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(blog), "-c", "user.name=Projectory Test", "-c", "user.email=test@example.invalid", "commit", "--allow-empty", "-m", "initial"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(blog), "worktree", "add", "-b", "feature/vista", str(worktree)], check=True, capture_output=True)
        cli("add", str(blog), "--name", "Blog")
        shop_id = next(record["id"] for record in json.loads(cli("list", "--json").stdout) if record["path"] == str(shop))
        env.update(SHOP=str(shop), OLD=str(old), RESERVED=str(reserved), WORKTREE=str(worktree), SHOP_ID=shop_id)

        shells = [name for name in ("zsh", "bash") if shutil.which(name)]
        assert shells, "zsh or bash is required for shell integration checks"

        def shell_argv(shell, code):
            return [shell, "-f" if shell == "zsh" else "--noprofile", "-c", 'eval "$("$PROJECTORY_BIN" init "$PROJECTORY_SHELL")"\n' + code]

        for shell in shells:
            shell_env = {**env, "PROJECTORY_SHELL": shell}
            before = visits()
            code = r'''
builtin cd -- "$ROOT"
pt "Mi Tienda" --db "$DB" || exit 10
[ "$PWD" = "$SHOP" ] || exit 11
builtin cd -- "$ROOT"
pt go 'mi tienda' --db "$DB" || exit 12
[ "$PWD" = "$SHOP" ] || exit 13
builtin cd -- "$ROOT"
pt go "$SHOP_ID" --db "$DB" || exit 14
[ "$PWD" = "$SHOP" ] || exit 15
builtin cd -- "$ROOT"
pt tiend --db "$DB" && exit 16
[ "$PWD" = "$ROOT" ] || exit 17
pt Blog --db "$DB" && exit 18
[ "$PWD" = "$ROOT" ] || exit 19
pt go add --db "$DB" || exit 20
[ "$PWD" = "$RESERVED" ] || exit 21
builtin cd -- "$ROOT"
pt --db "$DB" -- add || exit 22
[ "$PWD" = "$RESERVED" ] || exit 23
builtin cd -- "$ROOT"
pt add --help | grep -q -- --current || exit 24
pt list --plain --db "$DB" | grep -q 'Mi Tienda' || exit 25
[ "$PWD" = "$ROOT" ] || exit 26
'''
            result = subprocess.run(shell_argv(shell, code), cwd=root, env=shell_env, stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=60)
            assert result.returncode == 0, f"{shell}: exit {result.returncode}: {result.stderr}"
            assert '"tiend" no es un nombre exacto' in result.stderr, result.stderr
            assert '"Blog" tiene varias ubicaciones' in result.stderr, result.stderr
            after = visits()
            assert after[str(shop)] == before[str(shop)] + 3 and after[str(reserved)] == before[str(reserved)] + 2
            assert after[str(old)] == before[str(old)] and after[str(blog)] == before[str(blog)] == after[str(blog)]
            no_leftovers()
        print(f"PASS exact names, quoted spaces, IDs, reserved names, --, and non-interactive refusal in {', '.join(shells)}")

        for shell in shells:
            shell_env = {**env, "PROJECTORY_SHELL": shell}
            before = visits()
            code = r'''
builtin cd -- "$ROOT"
pt tiend --db "$DB" || exit 30
[ "$PWD" = "$OLD" ] || exit 31
printf '\n__NAVIGATION_CHOSEN__\n'
'''
            with Terminal(shell_argv(shell, code), shell_env, root, 100, 30) as terminal:
                terminal.expect("Coincidencias para «tiend»")
                terminal.expect("Mi Tienda")
                assert terminal.process.poll() is None and visits() == before, "approximate name navigated without confirmation"
                terminal.send("\r")
                assert "__NAVIGATION_CHOSEN__" in terminal.finish()
                assert ALTERNATE_SCREEN not in terminal.output, "the preview took over the terminal"
            after = visits()
            assert after[str(old)] == before[str(old)] + 1 and after[str(shop)] == before[str(shop)]
            no_leftovers()

            code = r'''
builtin cd -- "$ROOT"
pt tiend --db "$DB"
_status=$?
[ "$_status" -ne 0 ] || exit 40
[ "$PWD" = "$ROOT" ] || exit 41
pt tiend --db "$DB" && printf '__CHAINED__\n'
[ "$PWD" = "$ROOT" ] || exit 42
printf '\n__NAVIGATION_CANCELLED__\n'
'''
            with Terminal(shell_argv(shell, code), shell_env, root, 100, 30) as terminal:
                terminal.expect("Coincidencias para")
                changed_at = len(terminal.output)
                terminal.send("\x1b")  # One Esc cancels.
                terminal.expect("Coincidencias para", after=changed_at)
                terminal.send("\x03")  # Ctrl+C cancels as well.
                output = terminal.finish()
                assert "__NAVIGATION_CANCELLED__" in output and "__CHAINED__" not in output
                assert "projectory:" not in output, "cancellation printed an error"
            assert visits() == after, "cancellation counted a visit"
            no_leftovers()

            code = r'''
builtin cd -- "$ROOT"
pt Blog --db "$DB" || exit 50
[ "$PWD" = "$WORKTREE" ] || exit 51
printf '\n__NAVIGATION_LOCATION__\n'
'''
            with Terminal(shell_argv(shell, code), shell_env, root, 100, 30) as terminal:
                terminal.expect("Blog · 2 ubicaciones")
                terminal.expect("feature/vista")
                assert terminal.process.poll() is None, "a name with several locations was chosen automatically"
                terminal.resize(30, 6)
                terminal.resize(100, 30)
                changed_at = len(terminal.output)
                terminal.send("\x1b[B")
                terminal.expect("blog-vista", after=changed_at)
                terminal.send("\r")
                assert "__NAVIGATION_LOCATION__" in terminal.finish()
            final = visits()
            assert final[str(worktree)] == after[str(worktree)] + 1 and final[str(blog)] == after[str(blog)]
            no_leftovers()
        print(f"PASS inline approximate preview, Enter, Esc, Ctrl+C, several locations, resize, cd, and visits in {', '.join(shells)}")

        # A function loaded from 1.0.0 keeps working with this binary.
        for shell in shells:
            before = visits()
            code = LEGACY_FUNCTION.replace("BINARY", shlex.quote(str(binary))) + r'''
builtin cd -- "$ROOT"
pt go "$SHOP_ID" --db "$DB" || exit 60
[ "$PWD" = "$SHOP" ] || exit 61
pt list --plain --db "$DB" | grep -q 'Tienda Vieja' || exit 62
builtin cd -- "$ROOT"
[ "$(pt 'Mi Tienda' --db "$DB")" = "$SHOP" ] || exit 63
[ "$PWD" = "$ROOT" ] || exit 64
'''
            result = subprocess.run([shell, "-f" if shell == "zsh" else "--noprofile", "-c", code], cwd=root, env=env, stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=60)
            assert result.returncode == 0, f"{shell}: exit {result.returncode}: {result.stderr}"
            assert visits()[str(shop)] == before[str(shop)] + 1
            no_leftovers()
        print("PASS a 1.0.0 shell function still navigates by ID and lists with this binary")

    print("All navigation smoke checks passed.")


if __name__ == "__main__":
    main()
